def _append_params(oauth_params, params):
    # Convert params to a list of tuples if it's a dict
    if isinstance(params, dict):
        params = list(params.items())

    # Convert oauth_params to a list of tuples if it's a dict
    if isinstance(oauth_params, dict):
        oauth_params = list(oauth_params.items())

    # Create a list to hold the final parameters
    result = []

    # Add all non-OAuth parameters first (in order)
    for param in params:
        if not param[0].startswith('oauth_'):
            result.append(param)

    # Add all OAuth parameters (in order)
    for param in oauth_params:
        result.append(param)

    # Add remaining non-OAuth parameters (in order)
    for param in params:
        if not param[0].startswith('oauth_'):
            result.append(param)

    return result


def prepare_form_encoded_body(oauth_params, body):
    # If body is empty, return oauth_params as form-encoded string
    if not body:
        return urlencode(oauth_params)

    # Parse existing body into parameters
    existing_params = extract_params(body)

    # Append oauth_params to existing_params
    all_params = _append_params(oauth_params, existing_params)

    # Return the form-encoded string
    return urlencode(all_params)
